/usr/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
base=Path('.')
d=(base/'r1/etc/bind'); d.mkdir(parents=True,exist_ok=True)
(d/'named.conf.options').write_text('''options {
    directory \"/var/cache/bind\";
    listen-on { 127.0.0.1; 10.14.1.1; };
    listen-on-v6 { none; };
    allow-query { 10.14.0.0/16; 127.0.0.1; };
    recursion no;
};
''')
domains={'example.com': [('shop','10.14.3.11'),('mail','10.14.1.14')], 'service.com':[('api','10.14.3.12'),('mail','10.14.2.11')], 'lab.net':[('ai.research','10.14.4.12'),('data.research','10.14.4.13'),('mail','10.14.2.12')], 'tools.net':[('ci','10.14.4.11'),('mail','10.14.2.13')]}
(d/'named.conf.local').write_text(''.join(f'zone \"{domain}\" {{ type master; file \"/etc/bind/db.{domain}\"; }};\\n' for domain in domains))
for domain,records in domains.items():
    zone=f'''"'$TTL 3600
@ IN SOA ns.{domain}. hostmaster.{domain}. (
    2026103001 3600 600 604800 3600 )
  IN NS ns.{domain}.
  IN MX 10 mail.{domain}.
ns IN A 10.14.1.1
'"'''
    zone+=''.join(f'{name} IN A {ip}\\n' for name,ip in records)
    (d/f'db.{domain}').write_text(zone)
for i in range(1,21):
    p=base/f'pc{i}.startup'; s=p.read_text(); s += '\\n# DNS del laboratorio.\\nprintf \"nameserver 10.14.1.1\\\\n\" > /etc/resolv.conf\\n'; p.write_text(s)
p=base/'r1.startup'; p.write_text(p.read_text()+'\\n# Server DNS autorevole per i domini del laboratorio.\\nsystemctl restart bind9\\n')
p=base/'lab.conf'; s=p.read_text().replace('sola rete statica (senza DNS)', 'rete statica con DNS'); p.write_text(s)
PY
"

